package com.ben.csp.radiology;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Loads the REKORD layer-2 core inventory: how many atoms of each nuclide were
 * in the core at the instant of the accident.
 *
 * <p>The data file is generated by {@code tools/radiology/build_inventory.py},
 * which burns the lattice model to unit 4's 10.3 MWd/kg, tallies fissions per
 * fissile nuclide, and solves the decay-chain equations with fission as the
 * source. That last step is the whole point of this layer and is why the file
 * is not just yields times a fission count: the independent yield of Cs-137 is
 * 0.0006% per fission and its cumulative yield is 6.19%, the difference being
 * beta decay of its precursors over 618 days of irradiation. Multiplying either
 * number by the fission count gives a wrong inventory -- the first by orders of
 * magnitude, the second by a factor that depends on the nuclide's half-life.
 *
 * <p>This layer is atoms. It is not activity (that is atoms times the layer-1
 * decay constant), it is not a release, and it is not a dose. The distinction is
 * enforced: the file records {@code _notInThisFile} and the loader rejects an
 * entry that carries a release or an activity field, so a later layer cannot
 * quietly start reading a source term out of the inventory.
 */
public final class InventoryLoader {

    public static final String RESOURCE = "/data/csp/radiology/inventory.json";

    private static final List<String> PROBLEMS = new ArrayList<>();
    private static boolean loaded;

    private InventoryLoader() {}

    /** The loaded inventory, keyed by nuclide symbol ("Cs137"). */
    public static Map<String, InventoryEntry> inventory() {
        load();
        return Collections.unmodifiableMap(Inventory.INSTANCE.entries);
    }

    /** Total atoms over all nuclides. */
    public static double totalAtoms() {
        double sum = 0.0;
        for (InventoryEntry e : inventory().values()) {
            sum += e.atoms();
        }
        return sum;
    }

    /**
     * Atoms of one nuclide, or 0 if it is not in the inventory.
     *
     * <p>An isomer is asked for by its own symbol ("Xe135m"). It is a separate
     * node because it has its own half-life and its own independent yield, and
     * folding it into the ground state here would hide both.
     */
    public static double atoms(String symbol) {
        InventoryEntry e = inventory().get(symbol);
        return e == null ? 0.0 : e.atoms();
    }

    /**
     * Activity in becquerels, from the layer-2 atom count and the layer-1 decay
     * constant. This is the one sanctioned bridge between the two layers, and it
     * is computed rather than stored so a stale activity can never be read.
     * Returns 0 for a stable nuclide or one absent from layer 1.
     */
    public static double activityBq(String symbol) {
        double atoms = atoms(symbol);
        if (atoms <= 0.0) {
            return 0.0;
        }
        Isotope i = IsotopeRegistry.getInstance().getIsotope(symbol);
        return i == null ? 0.0 : atoms * i.decayConstant();
    }

    /** Fissions the inventory was built from, and the independent energy anchor. */
    public static FissionCount fissionCount() {
        load();
        return Inventory.INSTANCE.fissions;
    }

    public static synchronized int load() {
        if (loaded) {
            return Inventory.INSTANCE.entries.size();
        }
        loaded = true;
        try (InputStream in = InventoryLoader.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                PROBLEMS.add("data resource missing: " + RESOURCE);
                return 0;
            }
            JsonObject root = JsonParser.parseReader(
                new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
            if (root.has("_activity") || root.has("_release")) {
                PROBLEMS.add("inventory file carries activity or release data; "
                    + "layer 2 must contain atoms only");
                return 0;
            }
            Map<String, InventoryEntry> parsed = new LinkedHashMap<>();
            for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("nuclides").entrySet()) {
                InventoryEntry entry = parse(e.getKey(), e.getValue().getAsJsonObject());
                if (entry == null) {
                    continue;
                }
                if (parsed.put(entry.symbol(), entry) != null) {
                    PROBLEMS.add(entry.symbol() + ": duplicate symbol; isomers must "
                        + "carry their m suffix");
                }
            }
            Inventory.INSTANCE.entries.clear();
            Inventory.INSTANCE.entries.putAll(parsed);
            Inventory.INSTANCE.fissions = parseFissions(
                root.getAsJsonObject("_fissionCount"));
        } catch (Exception e) {
            PROBLEMS.add("failed to read " + RESOURCE + ": " + e);
            return 0;
        }
        return Inventory.INSTANCE.entries.size();
    }

    private static InventoryEntry parse(String key, JsonObject o) {
        Double atoms = dbl(o, "atoms");
        if (atoms == null || atoms < 0.0) {
            PROBLEMS.add(key + ": missing or negative atom count");
            return null;
        }
        Integer z = dbl(o, "z") == null ? null : dbl(o, "z").intValue();
        Integer a = dbl(o, "a") == null ? null : dbl(o, "a").intValue();
        if (z == null || a == null || z <= 0 || a <= 0) {
            PROBLEMS.add(key + ": missing Z or A");
            return null;
        }
        String symbol = o.has("symbol") ? o.get("symbol").getAsString() : null;
        if (symbol == null || symbol.isEmpty()) {
            PROBLEMS.add(key + ": missing symbol");
            return null;
        }
        return new InventoryEntry(key, symbol, z, a, atoms);
    }

    private static FissionCount parseFissions(JsonObject o) {
        if (o == null) {
            return new FissionCount(0.0, 0.0, Map.of(), 0.0, 0.0);
        }
        Map<String, Double> split = new LinkedHashMap<>();
        if (o.has("byNuclide")) {
            for (Map.Entry<String, JsonElement> e : o.getAsJsonObject("byNuclide").entrySet()) {
                split.put(e.getKey(), e.getValue().getAsDouble());
            }
        }
        return new FissionCount(
            dblOr(o, "total", 0.0),
            dblOr(o, "energyAnchor", 0.0),
            Collections.unmodifiableMap(split),
            dblOr(o, "fuelMassTU", 0.0),
            dblOr(o, "targetBurnupMWdPerKg", 0.0));
    }

    /** Nuclides whose record was unusable, with the reason. Empty means clean. */
    public static List<String> problems() {
        return Collections.unmodifiableList(PROBLEMS);
    }

    private static Double dbl(JsonObject o, String key) {
        return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsDouble() : null;
    }

    private static double dblOr(JsonObject o, String key, double fallback) {
        Double v = dbl(o, key);
        return v == null ? fallback : v;
    }

    /**
     * One nuclide's inventory: atoms, with Z and A so it can be grouped by
     * element and mass without re-parsing the symbol.
     *
     * @param key the data-file key ("55-137", "55-137m" for an isomer)
     * @param symbol nuclide symbol ("Cs137", "Cs137m")
     * @param z proton number
     * @param a mass number
     * @param atoms atoms present at shutdown
     */
    public record InventoryEntry(String key, String symbol, int z, int a, double atoms) {}

    /**
     * The fission tally the inventory was built from.
     *
     * @param total total fissions
     * @param energyAnchor the same burnup expressed as pure energy, an
     *        independent check on the tally
     * @param byNuclide fraction of fissions in each fissile nuclide
     * @param fuelMassTU uranium mass in tonnes
     * @param targetBurnupMWdPerKg burnup the core was taken to
     */
    public record FissionCount(double total, double energyAnchor,
                               Map<String, Double> byNuclide,
                               double fuelMassTU, double targetBurnupMWdPerKg) {
        /** The anchor as a percentage of the cell tally; 100 is perfect agreement. */
        public double agreementPercent() {
            return energyAnchor <= 0.0 ? 0.0 : 100.0 * total / energyAnchor;
        }
    }

    /** The single loaded inventory; a holder so {@link InventoryLoader} stays stateless. */
    private static final class Inventory {
        static final Inventory INSTANCE = new Inventory();
        final Map<String, InventoryEntry> entries = new LinkedHashMap<>();
        FissionCount fissions = new FissionCount(0.0, 0.0, Map.of(), 0.0, 0.0);
    }
}
